import org.gradle.api.Plugin
import org.gradle.api.Project

/**
 * The app side of baseline profiles: consumes the profile generated by :baselineprofile. On
 * build-logic's classpath because the androidx.baselineprofile plugin needs AGP.
 */
class BaselineProfileConsumerConventionPlugin : Plugin<Project> {
    override fun apply(target: Project) = target.pluginManager.apply("androidx.baselineprofile")
}

/** The producer side: a com.android.test module that generates the profile on a device. */
class BaselineProfileProducerConventionPlugin : Plugin<Project> {
    override fun apply(target: Project) =
        with(target.pluginManager) {
            apply("com.android.test")
            apply("androidx.baselineprofile")
        }
}
